n=19
orig=[[0]*n for _ in range(n)]
centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
for r,c,v in centers: orig[r][c]=v
for r,c,v in centers:
    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]: orig[r+dr][c+dc]=3
blank=(10,8)
for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]: orig[blank[0]+dr][blank[1]+dc]=3
# motif cell sets
motifs=[]
for r,c,v in centers:
    motifs.append({(r,c),(r-1,c),(r+1,c),(r,c-1),(r,c+1)})
blankcells={(blank[0],blank[1]),(blank[0]-1,blank[1]),(blank[0]+1,blank[1]),(blank[0],blank[1]-1),(blank[0],blank[1]+1)}
out=[row[:] for row in orig]
horiz=[[None]*n for _ in range(n)]
vert=[[None]*n for _ in range(n)]
for r,c,v in centers:
    for dr,dc,arr in [(0,-1,horiz),(0,1,horiz),(-1,0,vert),(1,0,vert)]:
        rr,cc=r,c
        while 0<=rr<n and 0<=cc<n:
            # source center/own arms allowed; first cell belonging to another motif blocks
            if (rr,cc)!=(r,c) and (rr,cc) not in motifs[centers.index((r,c))] and any((rr,cc) in m for m in motifs):
                break
            # draw color unless original nonzero
            if orig[rr][cc]==0:
                arr[rr][cc]=v
            rr+=dr;cc+=dc
# horizontal first, blank vertical erases only empty original cells along c8; then vertical rays overlay
for i in range(n):
    for j in range(n):
        if horiz[i][j] is not None and orig[i][j]==0: out[i][j]=horiz[i][j]
# blank vertical stripe, and blank horizontal stripe (both zero, only zeros in original)
for i in range(n):
    if orig[i][blank[1]]==0: out[i][blank[1]]=0
for j in range(n):
    if orig[blank[0]][j]==0: out[blank[0]][j]=0
for i in range(n):
    for j in range(n):
        if vert[i][j] is not None and orig[i][j]==0: out[i][j]=vert[i][j]
print('\n'.join(' '.join(map(str,row)) for row in out))

out=[row[:] for row in orig]
horiz=[[None]*n for _ in range(n)]; vert=[[None]*n for _ in range(n)]
for idx,(r,c,v) in enumerate(centers):
    own=motifs[idx]
    for dr,dc,arr in [(0,-1,horiz),(0,1,horiz),(-1,0,vert),(1,0,vert)]:
        rr,cc=r,c
        while 0<=rr<n and 0<=cc<n:
            if (rr,cc) not in own and any((rr,cc) in m for j,m in enumerate(motifs) if j!=idx):
                break
            if orig[rr][cc]==0: arr[rr][cc]=v
            rr+=dr;cc+=dc
for i in range(n):
    for j in range(n):
        if horiz[i][j] is not None and orig[i][j]==0: out[i][j]=horiz[i][j]
for i in range(n):
    if orig[i][blank[1]]==0: out[i][blank[1]]=0
for j in range(n):
    if orig[blank[0]][j]==0: out[blank[0]][j]=0
for i in range(n):
    for j in range(n):
        if vert[i][j] is not None and orig[i][j]==0: out[i][j]=vert[i][j]
print('\n'.join(' '.join(map(str,row)) for row in out))
